a = ""
b = "KEOIAKDKNDKHKILOMPPBLBMNDKMBAGEE"
e = "K##I#KDK##KHK###M##B#BMN##MBA###"
c = "KIHICKDKFHKHKCBAMAJBNBMNBGMBANBA"
d = "MAKBNBMCGKMBDBKKMBPBBBMMENMBBEKE"

filtered_blocks = []
positions_to_remove = [1, 2, 4, 8, 9, 13, 14, 15, 17, 18, 20, 24, 25, 29, 30, 31]
blocks = []

for i in range(0, len(a), 32):
    block = a[i:i + 32]

    # Заменяем символы на '#' на указанных позициях
    modified_block = ''.join([char if j not in positions_to_remove else '#' for j, char in enumerate(block)])

    # # Проверяем наличие нужных символов в модифицированном блоке
    # if (modified_block.count('N') >= 1 and modified_block.count('A') >= 1 and
    #         modified_block.count('K') >= 2 and modified_block.count('D') >= 1 and
    #         modified_block.count('I') >= 1 and modified_block.count('H') >= 1):
    blocks.append(modified_block)

# Выводим результат
for i, char in enumerate(blocks):
    print(f"i: {i} | blocks: \nбомб: {char[:16]}\na___: {char[16:32]}\n")

